import { IngestPipeline } from "@514labs/moose-lib";

export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number;
}

export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    // Optimize for the two query patterns:
    // 1. Activity counts per user over a date range: userId, eventTs
    // 2. Total duration per action type: action
    orderByFields: ["userId", "eventTs", "action"]
  },
  stream: true,
  ingestApi: true,
});

