const fs = require('fs');
const path = require('path');

// Read the CSV file
const csvPath = '/data/samples/user_activity_sample.csv';
const csvContent = fs.readFileSync(csvPath, 'utf8');

// Parse CSV to JSON
const lines = csvContent.trim().split('\n');
const headers = lines[0].split(',');
console.log('Headers:', headers);

const jsonData = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');
  if (values.length === headers.length) {
    const record = {
      eventId: values[0],
      eventTs: values[1],
      userId: values[2],
      action: values[3],
      durationMs: parseFloat(values[4]) || 0  // Default to 0 for null/empty values
    };
    jsonData.push(record);
  }
}

console.log(`Parsed ${jsonData.length} records`);
console.log('Sample record:', jsonData[0]);

// Send each record to the Moose ingestion endpoint
async function sendRecord(record) {
  const response = await fetch('http://localhost:4000/ingest/UserActivity', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(record)
  });

  return {
    status: response.status,
    ok: response.ok,
    record: record.eventId
  };
}

async function loadData() {
  console.log('Loading data to Moose...');

  for (let i = 0; i < jsonData.length; i++) {
    try {
      const result = await sendRecord(jsonData[i]);
      if (result.ok) {
        console.log(`✓ Loaded record ${i + 1}/${jsonData.length}: ${result.record}`);
      } else {
        console.log(`✗ Failed to load record ${result.record}: status ${result.status}`);
      }
    } catch (error) {
      console.log(`✗ Error loading record ${jsonData[i].eventId}:`, error.message);
    }

    // Small delay to avoid overwhelming the server
    if (i < jsonData.length - 1) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }
  }

  console.log('Data loading completed!');
}

loadData().catch(console.error);

